1	// Package store owns the SQLite file and every write the service performs.
2	package store
3	
4	import (
5		"context"
6		"database/sql"
7		"errors"
8		"fmt"
9		"strings"
10	
11		"github.com/xjeey8iust/sen-sbom-inventory/internal/model"
12		_ "modernc.org/sqlite"
13	)
14	
15	// Store wraps the SQLite handle so callers never touch database/sql directly.
16	type Store struct {
17		db *sql.DB
18	}
19	
20	// Open prepares the database file and the schema this service needs.
21	func Open(path string) (*Store, error) {
22		return open(path, "sqlite")
23	}
24	
25	// open is Open with an injectable driver name, which lets the package tests
26	// register a driver wrapper around the real SQLite driver.
27	func open(path, driverName string) (*Store, error) {
28		dsn := path
29		if strings.Contains(dsn, "?") {
30			dsn += "&"
31		} else {
32			dsn += "?"
33		}
34		// foreign_keys must be enabled per connection; busy_timeout lets a
35		// concurrent writer wait for an open write transaction instead of
36		// failing immediately with SQLITE_BUSY.
37		dsn += "_pragma=foreign_keys(1)&_pragma=busy_timeout(5000)"
38	
39		db, err := sql.Open(driverName, dsn)
40		if err != nil {
41			return nil, fmt.Errorf("open sqlite: %w", err)
42		}
43		if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
44			db.Close()
45			return nil, fmt.Errorf("enable wal: %w", err)
46		}
47		if _, err := db.Exec(schema); err != nil {
48			db.Close()
49			return nil, fmt.Errorf("apply schema: %w", err)
50		}
51		return &Store{db: db}, nil
52	}
53	
54	// Ping reports whether the storage layer is usable.
55	func (s *Store) Ping() error { return s.db.Ping() }
56	
57	// Close releases the database handle.
58	func (s *Store) Close() error { return s.db.Close() }
59	
60	// queryer is satisfied by *sql.DB, *sql.Tx and *sql.Conn.
61	type queryer interface {
62		ExecContext(ctx context.Context, query string, args ...any) (sql.Result, error)
63		QueryContext(ctx context.Context, query string, args ...any) (*sql.Rows, error)
64		QueryRowContext(ctx context.Context, query string, args ...any) *sql.Row
65	}
66	
67	// Register persists a normalized SBOM in a single write transaction. When the
68	// same artifact and version already hold an identical manifest, the existing
69	// record (with its original ID) is returned and created is false. Different
70	// content leaves the existing record untouched and returns model.ErrConflict.
71	func (s *Store) Register(ctx context.Context, in *model.SBOM) (sbom *model.SBOM, created bool, err error) {
72		c, err := s.db.Conn(ctx)
73		if err != nil {
74			return nil, false, unavailable(err)
75		}
76		defer c.Close()
77	
78		// BEGIN IMMEDIATE takes the writer lock up front, so two concurrent
79		// registrations for the same artifact/version serialize and the loser
80		// re-reads the winner's committed row instead of hitting the unique
81		// constraint.
82		if _, err := c.ExecContext(ctx, "BEGIN IMMEDIATE"); err != nil {
83			return nil, false, unavailable(err)
84		}
85		committed := false
86		defer func() {
87			if !committed {
88				// Best-effort cleanup; the original error is what callers need.
89				_, _ = c.ExecContext(context.Background(), "ROLLBACK")
90			}
91		}()
92	
93		var existingID int64
94		switch err := c.QueryRowContext(ctx,
95			"SELECT id FROM sboms WHERE artifact = ? AND version = ?",
96			in.Artifact, in.Version,
97		).Scan(&existingID); {
98		case err == nil:
99			existing, err := loadSBOM(ctx, c, existingID)
100			if err != nil {
101				return nil, false, err
102			}
103			if !equalContent(existing, in) {
104				return nil, false, model.ErrConflict
105			}
106			return existing, false, nil
107		case errors.Is(err, sql.ErrNoRows):
108			// Continue and insert.
109		default:
110			return nil, false, unavailable(err)
111		}
112	
113		res, err := c.ExecContext(ctx,
114			"INSERT INTO sboms (artifact, version) VALUES (?, ?)",
115			in.Artifact, in.Version)
116		if err != nil {
117			return nil, false, unavailable(err)
118		}
119		id, err := res.LastInsertId()
120		if err != nil {
121			return nil, false, unavailable(err)
122		}
123	
124		componentID := make(map[string]int64, len(in.Components))
125		insertComponent, err := c.PrepareContext(ctx,
126			"INSERT INTO components (sbom_id, coordinate, license) VALUES (?, ?, ?)")
127		if err != nil {
128			return nil, false, unavailable(err)
129		}
130		defer insertComponent.Close()
131		for i := range in.Components {
132			comp := &in.Components[i]
133			res, err := insertComponent.ExecContext(ctx, id, comp.Coordinate, comp.License)
134			if err != nil {
135				return nil, false, unavailable(err)
136			}
137			compID, err := res.LastInsertId()
138			if err != nil {
139				return nil, false, unavailable(err)
140			}
141			componentID[comp.Coordinate] = compID
142		}
143	
144		if depCount := countDependencies(in); depCount > 0 {
145			insertDep, err := c.PrepareContext(ctx,
146				"INSERT INTO dependencies (component_id, target_id) VALUES (?, ?)")
147			if err != nil {
148				return nil, false, unavailable(err)
149			}
150			defer insertDep.Close()
151			for i := range in.Components {
152				comp := &in.Components[i]
153				for _, dep := range comp.Dependencies {
154					if _, err := insertDep.ExecContext(ctx, componentID[comp.Coordinate], componentID[dep]); err != nil {
155						return nil, false, unavailable(err)
156					}
157				}
158			}
159		}
160	
161		if _, err := c.ExecContext(ctx, "COMMIT"); err != nil {
162			return nil, false, unavailable(err)
163		}
164		committed = true
165	
166		out := *in
167		out.ID = id
168		return &out, true, nil
169	}
170	
171	// List returns one page of complete SBOMs for an artifact ordered by ID, plus
172	// the total number of matching manifests. The count, the page manifests and
173	// the components/dependencies of that page are each read in one batched query
174	// (four SELECTs at most, regardless of page size) inside one transaction, so
175	// the total and the details share one committed snapshot and detail rows are
176	// never fetched for other pages or other artifacts.
177	func (s *Store) List(ctx context.Context, artifact string, page, pageSize int) (items []*model.SBOM, total int, err error) {
178		c, err := s.db.Conn(ctx)
179		if err != nil {
180			return nil, 0, unavailable(err)
181		}
182		defer c.Close()
183	
184		// A read transaction pins one snapshot for every SELECT below.
185		if _, err := c.ExecContext(ctx, "BEGIN"); err != nil {
186			return nil, 0, unavailable(err)
187		}
188		committed := false
189		defer func() {
190			if !committed {
191				// Best-effort cleanup; the original error is what callers need.
192				_, _ = c.ExecContext(context.Background(), "ROLLBACK")
193			}
194		}()
195	
196		if err := c.QueryRowContext(ctx,
197			"SELECT COUNT(*) FROM sboms WHERE artifact = ?", artifact,
198		).Scan(&total); err != nil {
199			return nil, 0, unavailable(err)
200		}
201	
202		rows, err := c.QueryContext(ctx,
203			"SELECT id, artifact, version FROM sboms WHERE artifact = ? ORDER BY id ASC LIMIT ? OFFSET ?",
204			artifact, pageSize, (page-1)*pageSize)
205		if err != nil {
206			return nil, 0, unavailable(err)
207		}
208		defer rows.Close()
209	
210		items = []*model.SBOM{}
211		ids := make([]int64, 0, pageSize)
212		indexByID := make(map[int64]int, pageSize)
213		for rows.Next() {
214			sbom := &model.SBOM{Components: []model.Component{}}
215			if err := rows.Scan(&sbom.ID, &sbom.Artifact, &sbom.Version); err != nil {
216				return nil, 0, unavailable(err)
217			}
218			ids = append(ids, sbom.ID)
219			indexByID[sbom.ID] = len(items)
220			items = append(items, sbom)
221		}
222		if err := rows.Err(); err != nil {
223			return nil, 0, unavailable(err)
224		}
225	
226		// Empty page (unknown artifact or a page past the last one): the count was
227		// already read, and the two detail queries must not run with an empty IN
228		// list. Total is still returned to the caller.
229		if len(ids) == 0 {
230			if _, err := c.ExecContext(ctx, "COMMIT"); err != nil {
231				return nil, 0, unavailable(err)
232			}
233			committed = true
234			return items, total, nil
235		}
236	
237		if err := loadPageComponents(ctx, c, items, ids, indexByID); err != nil {
238			return nil, 0, err
239		}
240		if err := loadPageDependencies(ctx, c, items, ids, indexByID); err != nil {
241			return nil, 0, err
242		}
243	
244		if _, err := c.ExecContext(ctx, "COMMIT"); err != nil {
245			return nil, 0, unavailable(err)
246		}
247		committed = true
248		return items, total, nil
249	}
250	
251	// loadPageComponents reads every component of the current page in one query
252	// and attaches the ordered components to their manifests.
253	func loadPageComponents(ctx context.Context, q queryer, items []*model.SBOM, ids []int64, indexByID map[int64]int) error {
254		query := `
255	SELECT c.sbom_id, c.coordinate, c.license
256	FROM components c
257	WHERE c.sbom_id IN (` + placeholders(len(ids)) + `)
258	ORDER BY c.sbom_id ASC, c.coordinate ASC`
259		args := int64Args(ids)
260		rows, err := q.QueryContext(ctx, query, args...)
261		if err != nil {
262			return unavailable(err)
263		}
264		defer rows.Close()
265	
266		for rows.Next() {
267			var sbomID int64
268			var comp model.Component
269			comp.Dependencies = []string{}
270			if err := rows.Scan(&sbomID, &comp.Coordinate, &comp.License); err != nil {
271				return unavailable(err)
272			}
273			items[indexByID[sbomID]].Components = append(items[indexByID[sbomID]].Components, comp)
274		}
275		return rowsError(rows.Err())
276	}
277	
278	// loadPageDependencies reads every dependency edge of the current page in one
279	// query. Both endpoints belong to the same manifest: the JOIN on sbom_id keeps
280	// edges scoped to the page and also prevents a target row from another version
281	// ever matching when coordinates repeat across versions.
282	func loadPageDependencies(ctx context.Context, q queryer, items []*model.SBOM, ids []int64, indexByID map[int64]int) error {
283		query := `
284	SELECT sc.sbom_id, sc.coordinate, tc.coordinate
285	FROM dependencies d
286	JOIN components sc ON sc.id = d.component_id
287	JOIN components tc ON tc.id = d.target_id AND tc.sbom_id = sc.sbom_id
288	WHERE sc.sbom_id IN (` + placeholders(len(ids)) + `)
289	ORDER BY sc.sbom_id ASC, sc.coordinate ASC, tc.coordinate ASC`
290		rows, err := q.QueryContext(ctx, query, int64Args(ids)...)
291		if err != nil {
292			return unavailable(err)
293		}
294		defer rows.Close()
295	
296		// Coordinates are unique within a manifest, so a (sbom ID, coordinate) pair
297		// locates the owning component even when two versions share a coordinate.
298		coordinateIndex := make(map[int64]map[string]int, len(items))
299		for _, sbom := range items {
300			byCoordinate := make(map[string]int, len(sbom.Components))
301			for j := range sbom.Components {
302				byCoordinate[sbom.Components[j].Coordinate] = j
303			}
304			coordinateIndex[sbom.ID] = byCoordinate
305		}
306	
307		for rows.Next() {
308			var sbomID int64
309			var from, to string
310			if err := rows.Scan(&sbomID, &from, &to); err != nil {
311				return unavailable(err)
312			}
313			comp := &items[indexByID[sbomID]].Components[coordinateIndex[sbomID][from]]
314			comp.Dependencies = append(comp.Dependencies, to)
315		}
316		return rowsError(rows.Err())
317	}
318	
319	// rowsError maps a drained cursor's terminal error without wrapping nil.
320	func rowsError(err error) error {
321		if err == nil {
322			return nil
323		}
324		return unavailable(err)
325	}
326	
327	// placeholders builds "?,?,?" for an IN-list of n values.
328	func placeholders(n int) string {
329		return strings.Repeat("?,", n-1) + "?"
330	}
331	
332	func int64Args(ids []int64) []any {
333		args := make([]any, len(ids))
334		for i, id := range ids {
335			args[i] = id
336		}
337		return args
338	}
339	
340	// loadSBOM reconstructs a single manifest with components ordered by
341	// coordinate and each component's dependencies ordered by the target
342	// coordinate. It is used by Register's idempotency/conflict check only; List
343	// takes the batched loaders above to stay within four SELECTs per page.
344	func loadSBOM(ctx context.Context, q queryer, id int64) (*model.SBOM, error) {
345		sbom := &model.SBOM{ID: id, Components: []model.Component{}}
346		if err := q.QueryRowContext(ctx,
347			"SELECT artifact, version FROM sboms WHERE id = ?", id,
348		).Scan(&sbom.Artifact, &sbom.Version); err != nil {
349			return nil, unavailable(err)
350		}
351	
352		componentRows, err := q.QueryContext(ctx,
353			"SELECT coordinate, license FROM components WHERE sbom_id = ? ORDER BY coordinate ASC", id)
354		if err != nil {
355			return nil, unavailable(err)
356		}
357		defer componentRows.Close()
358	
359		indexByCoordinate := make(map[string]int)
360		for componentRows.Next() {
361			var comp model.Component
362			comp.Dependencies = []string{}
363			if err := componentRows.Scan(&comp.Coordinate, &comp.License); err != nil {
364				return nil, unavailable(err)
365			}
366			indexByCoordinate[comp.Coordinate] = len(sbom.Components)
367			sbom.Components = append(sbom.Components, comp)
368		}
369		if err := componentRows.Err(); err != nil {
370			return nil, unavailable(err)
371		}
372	
373		depRows, err := q.QueryContext(ctx, `
374	SELECT sc.coordinate, tc.coordinate
375	FROM dependencies d
376	JOIN components sc ON sc.id = d.component_id
377	JOIN components tc ON tc.id = d.target_id AND tc.sbom_id = sc.sbom_id
378	WHERE sc.sbom_id = ?
379	ORDER BY sc.coordinate ASC, tc.coordinate ASC`, id)
380		if err != nil {
381			return nil, unavailable(err)
382		}
383		defer depRows.Close()
384	
385		for depRows.Next() {
386			var from, to string
387			if err := depRows.Scan(&from, &to); err != nil {
388				return nil, unavailable(err)
389			}
390			comp := &sbom.Components[indexByCoordinate[from]]
391			comp.Dependencies = append(comp.Dependencies, to)
392		}
393		if err := depRows.Err(); err != nil {
394			return nil, unavailable(err)
395		}
396		return sbom, nil
397	}
398	
399	// equalContent compares normalized manifests (sorted components and
400	// dependencies); artifact and version already matched in SQL.
401	func equalContent(a, b *model.SBOM) bool {
402		if len(a.Components) != len(b.Components) {
403			return false
404		}
405		for i := range a.Components {
406			x, y := &a.Components[i], &b.Components[i]
407			if x.Coordinate != y.Coordinate || x.License != y.License {
408				return false
409			}
410			if len(x.Dependencies) != len(y.Dependencies) {
411				return false
412			}
413			for j := range x.Dependencies {
414				if x.Dependencies[j] != y.Dependencies[j] {
415					return false
416				}
417			}
418		}
419		return true
420	}
421	
422	func countDependencies(in *model.SBOM) int {
423		n := 0
424		for i := range in.Components {
425			n += len(in.Components[i].Dependencies)
426		}
427		return n
428	}
429	
430	func unavailable(err error) error {
431		if errors.Is(err, model.ErrStorageUnavailable) {
432			return err
433		}
434		return fmt.Errorf("%w: %v", model.ErrStorageUnavailable, err)
435	}
436	
437	const schema = `
438	CREATE TABLE IF NOT EXISTS service_metadata (
439	    key   TEXT PRIMARY KEY,
440	    value TEXT NOT NULL
441	);
442	CREATE TABLE IF NOT EXISTS sboms (
443	    id       INTEGER PRIMARY KEY,
444	    artifact TEXT NOT NULL,
445	    version  TEXT NOT NULL,
446	    UNIQUE (artifact, version)
447	);
448	CREATE TABLE IF NOT EXISTS components (
449	    id         INTEGER PRIMARY KEY,
450	    sbom_id    INTEGER NOT NULL REFERENCES sboms(id) ON DELETE CASCADE,
451	    coordinate TEXT NOT NULL,
452	    license    TEXT NOT NULL,
453	    UNIQUE (sbom_id, coordinate)
454	);
455	CREATE TABLE IF NOT EXISTS dependencies (
456	    id           INTEGER PRIMARY KEY,
457	    component_id INTEGER NOT NULL REFERENCES components(id) ON DELETE CASCADE,
458	    target_id    INTEGER NOT NULL REFERENCES components(id) ON DELETE CASCADE,
459	    UNIQUE (component_id, target_id)
460	);
461	CREATE INDEX IF NOT EXISTS idx_sboms_artifact ON sboms(artifact);
462	`
463

