50	// Register registers the shared counting driver once and returns it,
51	// resetting its counters. Each test package runs in its own binary, so the
52	// fixed name does not collide across packages.
53	func Register() *Driver {
54		once.Do(func() {
55			shared = &Driver{inner: &sqlitedriver.Driver{}}
56			sql.Register(DriverName, shared)
57		})
58		shared.Reset()
59		return shared
60	}
