62	// Reset clears the observed counters and any pending fault.
63	func (d *Driver) Reset() {
64		d.mu.Lock()
65		d.stats.selects = 0
66		d.stats.rowsByKind = map[string]int{}
67		d.failKind = ""
68		d.mu.Unlock()
69	}
