71	// FailNextRead makes the next SELECT of kind
72	// ("count"/"sboms"/"components"/"dependencies") fail at the driver,
73	// simulating a storage read error.
74	func (d *Driver) FailNextRead(kind string) {
75		d.mu.Lock()
76		d.failKind = kind
77		d.mu.Unlock()
78	}
79	
80	// Snapshot returns a point-in-time copy of the counters.
81	func (d *Driver) Snapshot() Counters {
82		d.mu.Lock()
83		defer d.mu.Unlock()
84		rows := make(map[string]int, len(d.stats.rowsByKind))
85		for k, v := range d.stats.rowsByKind {
86			rows[k] = v
87		}
88		return Counters{Selects: d.stats.selects, RowsByKind: rows}
89	}
