99	// countingConn exposes the same legacy driver.Execer/driver.Queryer surface
100	// database/sql uses with the modernc driver; statements flow through Exec and
101	// Query where the counter lives.
102	type countingConn struct {
103		driver.Conn
104		driver *Driver
105	}
106	
107	func (c *countingConn) Exec(query string, args []driver.Value) (driver.Result, error) {
108		return c.Conn.(driver.Execer).Exec(query, args)
109	}
110	
111	// ResetSession and IsValid delegate the optional driver interfaces so pooled
112	// connections behave under the wrapper exactly as with the raw driver.
113	func (c *countingConn) ResetSession(ctx context.Context) error {
114		if resetter, ok := c.Conn.(driver.SessionResetter); ok {
115			return resetter.ResetSession(ctx)
116		}
117		return nil
118	}
119	
120	func (c *countingConn) IsValid() bool {
121		if validator, ok := c.Conn.(driver.Validator); ok {
122			return validator.IsValid()
123		}
124		return true
125	}
126	
127	func (c *countingConn) Query(query string, args []driver.Value) (driver.Rows, error) {
128		kind := SelectKind(query)
129		if kind != "" {
130			c.driver.mu.Lock()
131			fail := c.driver.failKind == kind
132			c.driver.mu.Unlock()
133			if fail {
134				return nil, errors.New("forced read failure from test driver")
135			}
136		}
137		rows, err := c.Conn.(driver.Queryer).Query(query, args)
138		if err != nil || kind == "" {
139			return rows, err
140		}
141		c.driver.mu.Lock()
142		c.driver.stats.selects++
143		c.driver.mu.Unlock()
144		return &countingRows{Rows: rows, driver: c.driver, kind: kind}, nil
145	}
146	
147	type countingRows struct {
148		driver.Rows
149		driver *Driver
150		kind   string
151	}
152	
153	func (r *countingRows) Next(dest []driver.Value) error {
154		err := r.Rows.Next(dest)
155		if err == nil {
156			r.driver.mu.Lock()
157			r.driver.stats.rowsByKind[r.kind]++
158			r.driver.mu.Unlock()
159		}
160		return err
161	}
162	
163	// SelectKind classifies the store's read statements. Transaction control, DDL
164	// and PRAGMAs return the empty string and are never counted.
165	func SelectKind(query string) string {
166		s := strings.ToUpper(strings.TrimSpace(query))
167		if !strings.HasPrefix(s, "SELECT") {
168			return ""
169		}
170		switch {
171		case strings.Contains(s, "COUNT(*)"):
172			return "count"
173		case strings.Contains(s, "FROM COMPONENTS C"):
174			return "components"
175		case strings.Contains(s, "FROM DEPENDENCIES D"):
176			return "dependencies"
177		default:
178			return "sboms"
179		}
180	}
