442					var got model.SBOM
443					json.Unmarshal(rec.Body.Bytes(), &got)
444					ids <- got.ID
445				}
446			}()
447		}
448		wg.Wait()
449		close(ids)
450		close(statuses)
451	
452		first := int64(-1)
453		for status := range statuses {
454			if status != http.StatusCreated {
455				t.Fatalf("concurrent register status = %d, want 201", status)
456			}
457		}
458		count := 0
459		for id := range ids {
460			if first == -1 {
461				first = id
462			} else if id != first {
463				t.Fatalf("concurrent registers produced ids %d and %d", first, id)
464			}
465			count++
466		}
467		if count != n {
468			t.Fatalf("created responses = %d, want %d", count, n)
469		}
470	}
471	
472	func TestStorageFailureMapsTo503(t *testing.T) {
473		st, err := store.Open(filepath.Join(t.TempDir(), "service.db"))
474		if err != nil {
475			t.Fatalf("open: %v", err)
476		}
477		router := NewRouter(st)
478		if err := st.Close(); err != nil {
479			t.Fatalf("close: %v", err)
480		}
481	
482		expectError(t, postSBOM(t, router, `{"artifact":"a","version":"1","components":[]}`),
483			http.StatusServiceUnavailable, "storage_unavailable")
484		expectError(t, getSBOMs(t, router, "/sboms?artifact=a"),
485			http.StatusServiceUnavailable, "storage_unavailable")
486	}
487	
488	func assertSBOMEqual(t *testing.T, got, want *model.SBOM) {
489		t.Helper()
490		if got.Artifact != want.Artifact || got.Version != want.Version {
491			t.Fatalf("artifact/version = %q/%q, want %q/%q", got.Artifact, got.Version, want.Artifact, want.Version)
492		}
493		if len(got.Components) != len(want.Components) {
494			t.Fatalf("components len = %d, want %d", len(got.Components), len(want.Components))
495		}
496		for i := range want.Components {
497			g, w := got.Components[i], want.Components[i]
498			if g.Coordinate != w.Coordinate || g.License != w.License {
499				t.Fatalf("component %d = %+v, want %+v", i, g, w)
500			}
501			if len(g.Dependencies) != len(w.Dependencies) {
502				t.Fatalf("deps of %s = %v, want %v", g.Coordinate, g.Dependencies, w.Dependencies)
503			}
504			for j := range w.Dependencies {
505				if g.Dependencies[j] != w.Dependencies[j] {
506					t.Fatalf("deps of %s = %v, want %v", g.Coordinate, g.Dependencies, w.Dependencies)
507				}
508			}
509		}
510	}
