18	// newCountedRouter builds the real HTTP router on a Store backed by the
19	// counting driver, so the SELECT budget can be measured for a whole request.
20	func newCountedRouter(t *testing.T) (*gin.Engine, *storetest.Driver) {
21		t.Helper()
22		counted := storetest.Register()
23		st, err := store.OpenWithDriver(filepath.Join(t.TempDir(), "counted-service.db"), storetest.DriverName)
24		if err != nil {
