31	// TestListRequestUsesAtMostFourSelects proves the end-to-end budget through
32	// the real HTTP handler: a page of one and a page of a hundred each issue
33	// exactly four SELECTs, and detail rows never cover anything off the page.
34	func TestListRequestUsesAtMostFourSelects(t *testing.T) {
35		register := func(router *gin.Engine, artifact, version, body string) {
36			t.Helper()
37			if rec := postSBOM(t, router, body); rec.Code != http.StatusCreated {
38				t.Fatalf("register %s@%s: %d %s", artifact, version, rec.Code, rec.Body.String())
39			}
40		}
41	
42		t.Run("one item", func(t *testing.T) {
43			router, counted := newCountedRouter(t)
44			register(router, "app", "1", `{"artifact":"app","version":"1","components":[
45				{"coordinate":"a","license":"A","dependencies":["b","c"]},
46				{"coordinate":"b","license":"B","dependencies":["c"]},
47				{"coordinate":"c","license":"C","dependencies":[]}
48			]}`)
49			counted.Reset()
50	
51			rec := getSBOMs(t, router, "/sboms?artifact=app")
52			if rec.Code != http.StatusOK {
53				t.Fatalf("status = %d, body %s", rec.Code, rec.Body.String())
54			}
55			counters := counted.Snapshot()
56			if counters.Selects > 4 {
57				t.Fatalf("request issued %d SELECTs, want at most 4", counters.Selects)
58			}
59			if counters.Selects != 4 {
60				t.Fatalf("non-empty page issued %d SELECTs, want exactly 4", counters.Selects)
61			}
62			if counters.RowsByKind["components"] != 3 || counters.RowsByKind["dependencies"] != 3 {
63				t.Fatalf("detail row counts wrong: %+v", counters.RowsByKind)
64			}
65		})
66	
67		t.Run("hundred items", func(t *testing.T) {
68			router, counted := newCountedRouter(t)
69			for i := 0; i < 100; i++ {
70				v := fmt.Sprintf("%02d", i)
71				body := fmt.Sprintf(`{"artifact":"app","version":"%s","components":[
72					{"coordinate":"a","license":"A","dependencies":["b"]},
73					{"coordinate":"b","license":"B","dependencies":[]}
74				]}`, v)
75				register(router, "app", v, body)
76			}
77			// A different artifact whose components share coordinates; never part
78			// of an "app" page.
79			register(router, "other", "1", `{"artifact":"other","version":"1","components":[
80				{"coordinate":"a","license":"SECRET","dependencies":[]}
81			]}`)
82			counted.Reset()
83	
84			rec := getSBOMs(t, router, "/sboms?artifact=app&pageSize=100")
85			if rec.Code != http.StatusOK {
86				t.Fatalf("status = %d, body %s", rec.Code, rec.Body.String())
87			}
88			counters := counted.Snapshot()
89			if counters.Selects != 4 {
90				t.Fatalf("100-item request issued %d SELECTs, want exactly 4", counters.Selects)
91			}
92			if counters.RowsByKind["sboms"] != 100 ||
93				counters.RowsByKind["components"] != 200 ||
94				counters.RowsByKind["dependencies"] != 100 {
95				t.Fatalf("detail reads escaped the page/artifact: %+v", counters.RowsByKind)
96			}
97	
98			var got listResponse
99			decodeBody(t, rec, &got)
100			if got.Total != 100 || len(got.Items) != 100 {
101				t.Fatalf("total/items = %d/%d", got.Total, len(got.Items))
102			}
103			for _, item := range got.Items {
104				if item.Artifact != "app" {
105					t.Fatalf("foreign item on page: %q", item.Artifact)
106				}
107				for _, c := range item.Components {
108					if c.License == "SECRET" {
109						t.Fatalf("other artifact's component leaked: %+v", c)
110					}
111				}
112			}
113		})
114	
115		t.Run("empty page", func(t *testing.T) {
116			router, counted := newCountedRouter(t)
117			register(router, "app", "1", `{"artifact":"app","version":"1","components":[]}`)
118			counted.Reset()
119	
120			// Unknown artifact: count plus page scan, and the detail queries must
121			// not run against an empty IN-list.
122			rec := getSBOMs(t, router, "/sboms?artifact=ghost")
123			if rec.Code != http.StatusOK {
124				t.Fatalf("status = %d", rec.Code)
125			}
126			counters := counted.Snapshot()
127			if counters.Selects > 4 {
128				t.Fatalf("SELECTs = %d, want at most 4", counters.Selects)
129			}
130			if counters.Selects != 2 || counters.RowsByKind["components"] != 0 || counters.RowsByKind["dependencies"] != 0 {
131				t.Fatalf("empty page issued %d selects, rows %+v; want 2 and no details",
132					counters.Selects, counters.RowsByKind)
133			}
134		})
135	}
