137	// TestListServesCompleteManifestsAcrossPages verifies through HTTP that every
138	// manifest on every page is complete: components and dependencies ordered,
139	// empty arrays present, cycles intact and coordinates correctly scoped when
140	// versions repeat them.
141	func TestListServesCompleteManifestsAcrossPages(t *testing.T) {
142		router, _ := newCountedRouter(t)
143	
144		// Three versions of "app" share coordinates but differ in license/edges.
145		bodies := []string{
146			`{"artifact":"app","version":"1","components":[
147				{"coordinate":"lib","license":"Apache-2.0","dependencies":["util"]},
148				{"coordinate":"util","license":"BSD-3-Clause","dependencies":[]}
149			]}`,
150			`{"artifact":"app","version":"2","components":[
151				{"coordinate":"lib","license":"GPL-3.0","dependencies":[]},
152				{"coordinate":"util","license":"MIT","dependencies":["lib"]}
153			]}`,
154			`{"artifact":"app","version":"3","components":[
155				{"coordinate":"lib","license":"ISC","dependencies":["util"]},
156				{"coordinate":"util","license":"Unlicense","dependencies":["lib"]}
157			]}`,
158		}
159		// Plus an empty manifest.
160		bodies = append(bodies, `{"artifact":"app","version":"empty","components":[]}`)
161		// Plus another artifact that must never appear on "app" pages.
162		bodies = append(bodies, `{"artifact":"vendor","version":"1","components":[
163			{"coordinate":"lib","license":"PROPRIETARY","dependencies":[]}
164		]}`)
165		for _, body := range bodies {
166			if rec := postSBOM(t, router, body); rec.Code != http.StatusCreated {
167				t.Fatalf("register: %d %s", rec.Code, rec.Body.String())
168			}
169		}
170	
171		// Walk every page with pageSize=2 and collect the complete "app" result.
172		var collected []*model.SBOM
173		total := -1
174		for page := 1; ; page++ {
175			rec := getSBOMs(t, router, fmt.Sprintf("/sboms?artifact=app&page=%d&pageSize=2", page))
176			if rec.Code != http.StatusOK {
177				t.Fatalf("page %d: %d %s", page, rec.Code, rec.Body.String())
178			}
179			var got listResponse
180			decodeBody(t, rec, &got)
181			if got.Total != 4 {
182				t.Fatalf("page %d total = %d, want 4", page, got.Total)
183			}
184			if got.Page != page || got.PageSize != 2 {
185				t.Fatalf("page echo = %d/%d", got.Page, got.PageSize)
186			}
187			total = got.Total
188			if len(got.Items) == 0 {
189				break
190			}
191			collected = append(collected, got.Items...)
192			if page > 5 {
193				t.Fatalf("pagination did not terminate")
194			}
195		}
196		if len(collected) != total {
197			t.Fatalf("collected %d items across pages, want total %d", len(collected), total)
198		}
199	
200		byVersion := map[string]*model.SBOM{}
201		var prevID int64
202		for i, item := range collected {
203			if i > 0 && item.ID <= prevID {
204				t.Fatalf("items not ascending by id across pages: %d after %d", item.ID, prevID)
205			}
206			prevID = item.ID
207			if item.Artifact != "app" {
208				t.Fatalf("foreign artifact on page: %q", item.Artifact)
209			}
210			byVersion[item.Version] = item
211		}
212	
213		empty, ok := byVersion["empty"]
214		if !ok {
215			t.Fatalf("empty manifest missing across pages")
216		}
217		if empty.Components == nil || len(empty.Components) != 0 {
218			t.Fatalf("empty components = %v, want [] not null", empty.Components)
219		}
220	
221		type expectation struct {
222			libLicense, utilLicense string
223			libDeps, utilDeps       []string
224		}
225		want := map[string]expectation{
226			"1": {"Apache-2.0", "BSD-3-Clause", []string{"util"}, []string{}},
227			"2": {"GPL-3.0", "MIT", []string{}, []string{"lib"}},
228			"3": {"ISC", "Unlicense", []string{"util"}, []string{"lib"}},
229		}
230		for version, exp := range want {
231			item := byVersion[version]
232			comps := map[string]model.Component{}
233			for _, c := range item.Components {
234				comps[c.Coordinate] = c
235				if c.Dependencies == nil {
236					t.Fatalf("version %s component %s dependencies are null", version, c.Coordinate)
237				}
238			}
239			if len(item.Components) != 2 {
240				t.Fatalf("version %s lost components across pages: %+v", version, item.Components)
241			}
242			if comps["lib"].License != exp.libLicense || !eqStrings(comps["lib"].Dependencies, exp.libDeps) {
243				t.Fatalf("version %s lib = %+v, want %q %v", version, comps["lib"], exp.libLicense, exp.libDeps)
244			}
245			if comps["util"].License != exp.utilLicense || !eqStrings(comps["util"].Dependencies, exp.utilDeps) {
246				t.Fatalf("version %s util = %+v, want %q %v", version, comps["util"], exp.utilLicense, exp.utilDeps)
247			}
248		}
249	
250		// A legal cycle must read back completely through the batched loader.
251		cycleBody := `{"artifact":"cyc","version":"1","components":[
252			{"coordinate":"a","license":"A","dependencies":["b"]},
253			{"coordinate":"b","license":"B","dependencies":["a"]}
254		]}`
255		if rec := postSBOM(t, router, cycleBody); rec.Code != http.StatusCreated {
256			t.Fatalf("register cycle: %d %s", rec.Code, rec.Body.String())
257		}
258		rec := getSBOMs(t, router, "/sboms?artifact=cyc")
259		var cyc listResponse
260		decodeBody(t, rec, &cyc)
261		if len(cyc.Items) != 1 {
262			t.Fatalf("cycle items = %d", len(cyc.Items))
263		}
264		edges := map[string][]string{}
265		for _, c := range cyc.Items[0].Components {
266			edges[c.Coordinate] = c.Dependencies
267		}
268		if len(edges["a"]) != 1 || edges["a"][0] != "b" || len(edges["b"]) != 1 || edges["b"][0] != "a" {
269			t.Fatalf("dependency cycle not read back completely: %+v", edges)
270		}
271	}
272	
273	// TestListEmptyArraysAreNeverNull inspects the raw JSON so the guarantee is
274	// proven at the wire level, not just on Go structs.
275	func TestListEmptyArraysAreNeverNull(t *testing.T) {
276		router, _ := newCountedRouter(t)
277		postSBOM(t, router, `{"artifact":"app","version":"1","components":[]}`)
278		postSBOM(t, router, `{"artifact":"app","version":"2","components":[
279			{"coordinate":"a","license":"A","dependencies":[]}
280		]}`)
281	
282		rec := getSBOMs(t, router, "/sboms?artifact=app")
283		body := rec.Body.Bytes()
284		if !json.Valid(body) {
285			t.Fatalf("invalid json: %s", body)
286		}
287		var raw struct {
288			Items []struct {
289				Components *[]struct {
290					Dependencies *[]string `json:"dependencies"`
291				} `json:"components"`
292			} `json:"items"`
293		}
294		if err := json.Unmarshal(body, &raw); err != nil {
295			t.Fatalf("decode: %v", err)
296		}
297		if len(raw.Items) != 2 {
298			t.Fatalf("items = %d", len(raw.Items))
299		}
300		if raw.Items[0].Components == nil {
301			t.Fatalf("empty components serialized as null")
302		}
303		if raw.Items[1].Components == nil || len(*raw.Items[1].Components) != 1 {
304			t.Fatalf("second item components wrong")
305		}
306		if (*raw.Items[1].Components)[0].Dependencies == nil {
307			t.Fatalf("empty dependencies serialized as null")
308		}
309	}
310	
311	// TestListStorageFailureReturns503WithoutPartialItems forces each of the four
312	// reads to fail and asserts the HTTP contract: 503, single top-level error,
313	// storage_unavailable code, no partial items, no internals leaked.
314	func TestListStorageFailureReturns503WithoutPartialItems(t *testing.T) {
315		for _, kind := range []string{"count", "sboms", "components", "dependencies"} {
316			t.Run(kind, func(t *testing.T) {
317				router, counted := newCountedRouter(t)
318				postSBOM(t, router, `{"artifact":"app","version":"1","components":[
319					{"coordinate":"a","license":"A","dependencies":["b"]},
320					{"coordinate":"b","license":"B","dependencies":[]}
321				]}`)
322				counted.FailNextRead(kind)
323	
324				rec := getSBOMs(t, router, "/sboms?artifact=app")
325				if rec.Code != http.StatusServiceUnavailable {
326					t.Fatalf("%s failure: status = %d, want 503; body %s", kind, rec.Code, rec.Body.String())
327				}
328				var envelope struct {
329					Error struct {
330						Code    string `json:"code"`
331						Message string `json:"message"`
332					} `json:"error"`
333					Items json.RawMessage `json:"items"`
334				}
335				decodeBody(t, rec, &envelope)
336				if envelope.Error.Code != "storage_unavailable" {
337					t.Fatalf("code = %q", envelope.Error.Code)
338				}
339				if envelope.Error.Message == "" {
340					t.Fatalf("empty error message")
341				}
342				if envelope.Items != nil {
343					t.Fatalf("partial items present on failure: %s", envelope.Items)
344				}
345				for _, leaked := range []string{"SELECT", "SQLITE", "sql:", "goroutine", ".go:", "forced read failure"} {
346					if bytes.Contains(rec.Body.Bytes(), []byte(leaked)) {
347						t.Fatalf("response leaks %q: %s", leaked, rec.Body.String())
348					}
349				}
350			})
351		}
352	}
353	
354	// TestListTrimsArtifactAndEchoesPaging covers the request normalization and
355	// response echo semantics on the refactored path.
356	func TestListTrimsArtifactAndEchoesPaging(t *testing.T) {
357		router, _ := newCountedRouter(t)
358		postSBOM(t, router, `{"artifact":"  app  ","version":"1","components":[]}`)
359	
360		rec := getSBOMs(t, router, "/sboms?artifact=%20%20app%20%20&page=3&pageSize=50")
361		if rec.Code != http.StatusOK {
362			t.Fatalf("status = %d, body %s", rec.Code, rec.Body.String())
363		}
364		var got listResponse
365		decodeBody(t, rec, &got)
366		// Trimmed artifact matches the single manifest; past-end page keeps total.
367		if got.Total != 1 || len(got.Items) != 0 {
368			t.Fatalf("trimmed filter = %+v", got)
369		}
370		if got.Page != 3 || got.PageSize != 50 {
371			t.Fatalf("paging echo = %d/%d", got.Page, got.PageSize)
372		}
373	
374		// Case sensitivity: "APP" matches nothing.
375		rec = getSBOMs(t, router, "/sboms?artifact=APP")
376		decodeBody(t, rec, &got)
377		if got.Total != 0 || len(got.Items) != 0 {
378			t.Fatalf("case-insensitive leak: %+v", got)
379		}
380	}
381	
382	func eqStrings(a, b []string) bool {
383		if len(a) != len(b) {
384			return false
385		}
386		for i := range a {
387			if a[i] != b[i] {
388				return false
389			}
390		}
391		return true
392	}
